#!/bin/sh
# Starts vsftpd from files generated by cnc-admin:
#   /etc/cnc/vsftpd.conf      vsftpd configuration
#   /etc/cnc/ftp-users.txt    "<username> <sha512-crypt hash> <machine IP>" per line
set -eu

: "${CNC_UID:?}" "${CNC_GID:?}"

for f in /etc/cnc/vsftpd.conf /etc/cnc/ftp-users.txt; do
    [ -f "$f" ] || { echo "Missing $f (run: docker compose run --rm cnc-admin python -m cncadmin.cli init)" >&2; exit 1; }
done
cp /etc/cnc/vsftpd.conf /etc/vsftpd.conf

getent group cncfiles >/dev/null || groupadd -g "$CNC_GID" cncfiles
getent passwd cncfiles >/dev/null || useradd -M -N -u "$CNC_UID" -g cncfiles -s /usr/sbin/nologin cncfiles

# "docker restart" keeps the container filesystem: drop users from the previous run.
for u in $(awk -F: '$5 == "cnc-managed" { print $1 }' /etc/passwd); do
    userdel "$u"
done
: > /etc/vsftpd.user_list
# Each login is only accepted from its own machine's IP (pam_access).
: > /etc/security/vsftpd-access.conf
grep -q pam_access /etc/pam.d/vsftpd ||
    echo "account required pam_access.so accessfile=/etc/security/vsftpd-access.conf" >> /etc/pam.d/vsftpd

# Every FTP login shares the cncfiles UID, so files are owned the same as over SMB.
grep -v '^[[:space:]]*\(#\|$\)' /etc/cnc/ftp-users.txt | while read -r user hash ip; do
    if ! useradd -o -M -N -u "$CNC_UID" -g cncfiles -c cnc-managed -d "/srv/cnc/$user" \
            -s /usr/sbin/nologin -p "$hash" "$user"; then
        echo "WARNING: could not create user '$user'; skipped" >&2
        continue
    fi
    echo "$user" >> /etc/vsftpd.user_list
    echo "+ : $user : $ip" >> /etc/security/vsftpd-access.conf
    echo "FTP user ready: $user"
done

echo "- : ALL : ALL" >> /etc/security/vsftpd-access.conf

# Normally created by systemd-tmpfiles, which doesn't run in the container.
mkdir -p /var/run/vsftpd/empty
touch /var/log/vsftpd.log
tail -F /var/log/vsftpd.log &
exec vsftpd /etc/vsftpd.conf
